INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kann ich Fehler ohne Logs identifizieren?', 2, '[{"text": "Nein", "correct": true, "because": "Logs geben Kontext"}, {"text": "Ja", "correct": false, "because": "Ohne Logs ungenau"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit der Fehleridentifikation?', 3, '[{"text": "Problembehebung", "correct": true, "because": "Löst Bugs"}, {"text": "Performance", "correct": false, "because": "Indirekt"}, {"text": "Design", "correct": false, "because": "Anderer Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden helfen bei der Fehleridentifikation?', 5, '[{"text": "Log-Analyse", "correct": true, "because": "Zeigt Fehlerdetails"}, {"text": "Debugging", "correct": true, "because": "Verfolgt Ablauf"}, {"text": "Zufälliges Raten", "correct": false, "because": "Unzuverlässig"}, {"text": "UI-Tests", "correct": false, "because": "Oberflächlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Logs zeigen Fehlerursachen. b) Debugging ist optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) oft nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Fehleridentifikation?', 4, '[{"text": "Fehlermeldungen", "correct": false, "because": "Zeigen Problem"}, {"text": "Zeitstempel", "correct": false, "because": "Gibt Kontext"}, {"text": "Schriftfarbe", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Fehler immer reproduzierbar sind?', 2, '[{"text": "Nein", "correct": true, "because": "Manche sind zufällig"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool nutze ich für die Log-Analyse?', 3, '[{"text": "ELK Stack", "correct": true, "because": "Effizient für Logs"}, {"text": "Notepad", "correct": false, "because": "Unpraktisch"}, {"text": "E-Mail", "correct": false, "because": "Unstrukturiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen Fehleridentifikation effektiv?', 5, '[{"text": "Detaillierte Logs", "correct": true, "because": "Mehr Infos"}, {"text": "Reproduktion", "correct": true, "because": "Bestätigt Fehler"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Irrelevant"}, {"text": "Lange Texte", "correct": false, "because": "Ermüdend"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Fehler sind immer im Code. b) Logs sind überflüssig. Stimmt das?', 3, '[{"text": "Beides falsch", "correct": true, "because": "Auch Konfig, Logs essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "Nicht korrekt"}, {"text": "Nur a) stimmt", "correct": false, "because": "a) unvollständig"}, {"text": "Nur b) stimmt", "correct": false, "because": "b) falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Fehleridentifikation?', 4, '[{"text": "Log-Dateien", "correct": false, "because": "Hauptquelle"}, {"text": "Stacktrace", "correct": false, "because": "Zeigt Ablauf"}, {"text": "Monitorgröße", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Fehler immer offensichtlich?', 2, '[{"text": "Nein", "correct": true, "because": "Manche versteckt"}, {"text": "Ja", "correct": false, "because": "Nicht immer klar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Infos sind bei der Log-Analyse entscheidend?', 4, '[{"text": "Zeitstempel", "correct": true, "because": "Zeigt Wann"}, {"text": "Fehlercodes", "correct": true, "because": "Identifiziert Problem"}, {"text": "UI-Design", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Fehleridentifikation ohne Tools möglich ist. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Manuell machbar"}, {"text": "Nein", "correct": false, "because": "Tools effizienter"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Fehleridentifikation?', 3, '[{"text": "Genauigkeit", "correct": true, "because": "Richtige Ursache finden"}, {"text": "Schnelligkeit", "correct": false, "because": "Qualität zählt"}, {"text": "Vermutungen", "correct": false, "because": "Unzuverlässig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Log-Analyse braucht Zeitstempel. b) Fehler sind immer reproduzierbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) nicht immer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine gute Fehleridentifikation?', 5, '[{"text": "Schnelle Lösung", "correct": true, "because": "Ursache klar"}, {"text": "Weniger Ausfälle", "correct": true, "because": "Präventiv"}, {"text": "Hohe Kosten", "correct": false, "because": "Kein Vorteil"}, {"text": "Schnelle Tests", "correct": false, "because": "Indirekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Fehleridentifikation unwichtig?', 3, '[{"text": "Fehlermeldung", "correct": false, "because": "Zeigt Problem"}, {"text": "Log-Level", "correct": false, "because": "Filtert Relevanz"}, {"text": "Papierformat", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ersetzt Debugging die Log-Analyse?', 3, '[{"text": "Nein", "correct": true, "because": "Ergänzen sich"}, {"text": "Ja", "correct": false, "because": "Logs breiter"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Fehler immer im Log sichtbar sind?', 2, '[{"text": "Nein", "correct": true, "because": "Manche ungeloggt"}, {"text": "Ja", "correct": false, "because": "Nicht garantiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature ist für die Fehleridentifikation entscheidend?', 4, '[{"text": "Detailtiefe", "correct": true, "because": "Genauere Ursache"}, {"text": "Hohe Komplexität", "correct": false, "because": "Verwirrt"}, {"text": "Statische Daten", "correct": false, "because": "Nicht primär"}]');
